INSERT INTO training_quizzes (title, title_ar, description, description_ar, passing_score) VALUES
('Translation Fundamentals', 'أساسيات الترجمة', 'Test your knowledge of Arabic translation basics', 'اختبر معرفتك بأساسيات الترجمة العربية', 70);

SET @quiz1_id = LAST_INSERT_ID();

-- Question 1
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz1_id, 'What is the correct Arabic punctuation mark for a comma?', 'ما هي علامة الترقيم العربية الصحيحة للفاصلة؟', '،', 'Arabic uses ، (Arabic comma) instead of , (English comma)', 'العربية تستخدم ، (الفاصلة العربية) بدلاً من , (الفاصلة الإنجليزية)', 0);

SET @q1_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q1_id, ',', ',', FALSE, 0),
(@q1_id, '،', '،', TRUE, 1),
(@q1_id, ';', ';', FALSE, 2),
(@q1_id, '؛', '؛', FALSE, 3);

-- Question 2
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz1_id, 'Which tone should be used for business services translation?', 'ما اللهجة التي يجب استخدامها لترجمة الخدمات التجارية؟', 'Formal Arabic (MSA)', 'Business and government services require Modern Standard Arabic (الفصحى)', 'الخدمات التجارية والحكومية تتطلب اللغة العربية الفصحى الحديثة', 1);

SET @q2_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q2_id, 'Colloquial dialect', 'لهجة عامية', FALSE, 0),
(@q2_id, 'Formal Arabic (MSA)', 'عربية فصحى', TRUE, 1),
(@q2_id, 'Mixed formal and informal', 'مزيج رسمي وغير رسمي', FALSE, 2),
(@q2_id, 'Classical Arabic', 'عربية كلاسيكية', FALSE, 3);

-- Question 3
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz1_id, 'What is the correct translation for "Browse offices"?', 'ما هي الترجمة الصحيحة لـ "Browse offices"؟', 'استعرض المكاتب', 'استعرض is more natural than the literal تصفح for this context', 'استعرض أكثر طبيعية من الحرفي تصفح في هذا السياق', 2);

SET @q3_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q3_id, 'تصفح المكاتب', 'تصفح المكاتب', FALSE, 0),
(@q3_id, 'استعرض المكاتب', 'استعرض المكاتب', TRUE, 1),
(@q3_id, 'شاهد المكاتب', 'شاهد المكاتب', FALSE, 2),
(@q3_id, 'ابحث المكاتب', 'ابحث المكاتب', FALSE, 3)

